const assert = require('node:assert/strict');
const { execFileSync } = require('node:child_process');
const path = require('node:path');
const { test } = require('node:test');
const { normalize, inspectPullRequest, run } = require('./attribution.cjs');
const branches = require('./fixtures/branches.json');

const root = path.resolve(__dirname, '../..');
const identity = { name: 'BichengWang', email: 'bichengwang17@gmail.com' };
const cleanCommit = {
  sha: 'a'.repeat(40), message: 'Add workflow checks', author: identity, committer: identity,
};
const cleanPR = {
  actor: 'BichengWang', branch: 'agents/eval-harness', title: 'Add workflow checks',
  body: 'Run the offline checks on pull requests.', commits: [cleanCommit],
};

function git(...args) {
  return execFileSync('git', args, { cwd: root, encoding: 'utf8' });
}

test('last 30 commits pass message and identity rules', t => {
  const fields = git('log', '-30', '--format=%H%x00%an%x00%ae%x00%cn%x00%ce%x00%B%x00')
    .split('\0').slice(0, -1);
  assert.equal(fields.length, 30 * 6, 'A full checkout with at least 30 commits is required.');
  for (let index = 0; index < fields.length; index += 6) {
    const [sha, authorName, authorEmail, committerName, committerEmail, message] = fields.slice(index, index + 6);
    const commit = {
      sha: sha.trim(), message,
      author: { name: authorName, email: authorEmail },
      committer: { name: committerName, email: committerEmail },
    };
    assert.deepEqual(inspectPullRequest({ commits: [commit] }).denied, [], commit.sha);
    t.diagnostic(`PASS commit ${commit.sha.slice(0, 7)} ${message.split('\n')[0]}`);
  }
});

test('merge subjects, local refs and preserved PR branches have the expected results', t => {
  const forbiddenPRs = new Set([32, 33, 34, 35, 36]);
  const history = git('log', '-30', '--format=%s').split('\n').flatMap(subject => {
    const match = /^Merge pull request #(\d+) from (\S+)/u.exec(subject);
    return match ? [{ number: Number(match[1]), branch: match[2] }] : [];
  });
  const refs = git('for-each-ref', '--format=%(refname)', 'refs/heads', 'refs/remotes')
    .trim().split('\n').filter(ref => !ref.endsWith('/HEAD'))
    .map(ref => {
      const branch = ref.replace(/^refs\/(heads\/|remotes\/[^/]+\/)/u, '');
      return { branch, number: branches.find(record => record.branch === branch)?.number };
    });
  const failedPRs = [];
  // The public PR API preserves branches missing from squash merges or deleted refs.
  for (const record of [...history, ...refs, ...branches]) {
    const denied = inspectPullRequest({ branch: record.branch }).denied.length > 0;
    assert.equal(denied, forbiddenPRs.has(record.number), record.branch);
    if (denied) failedPRs.push(record.number);
    t.diagnostic(`${denied ? 'FAIL (expected)' : 'PASS'} ${record.number ? `#${record.number} ` : ''}${record.branch}`);
  }
  assert.deepEqual([...new Set(failedPRs)].sort((a, b) => a - b), [...forbiddenPRs]);
});

test('synthetic prohibited branches, text and identities fail', t => {
  const cases = [
    ['vendor branch', { branch: 'codex/x' }],
    ['owner-prefixed branch', { branch: 'BichengWang/Claude-sdk' }],
    ['zero-width branch', { branch: 'co\u200Bdex/x' }],
    ['fullwidth branch', { branch: 'ｃｏｄｅｘ/x' }],
    ['bidi branch', { branch: 'co\u202Edex/x' }],
    ['generated body', { body: 'Generated with Codex' }],
    ['generated title', { title: 'Generated by Claude' }],
    ['zero-width body', { body: 'Generated with Co\u2060dex' }],
    ['fullwidth body', { body: 'Ｇｅｎｅｒａｔｅｄ ｗｉｔｈ Ｃｏｄｅｘ' }],
    ['coauthor trailer', { commits: [{ ...cleanCommit, message: 'Add checks\n\nCo-authored-by: Claude <noreply@example.com>' }] }],
    ['coauthor email', { commits: [{ ...cleanCommit, message: 'Co-authored-by: Helper <helper@openai.com>' }] }],
    ['author email', { commits: [{ ...cleanCommit, author: { ...identity, email: 'helper@anthropic.com' } }] }],
    ['committer name', { commits: [{ ...cleanCommit, committer: { ...identity, name: 'Codex' } }] }],
    ['fullwidth identity', { commits: [{ ...cleanCommit, author: { ...identity, name: 'Ｃｌａｕｄｅ' } }] }],
    ['zero-width email', { commits: [{ ...cleanCommit, committer: { ...identity, email: 'helper@op\u200Benai.com' } }] }],
  ];
  for (const [label, changes] of cases) {
    assert.ok(inspectPullRequest({ ...cleanPR, ...changes }).denied.length > 0, label);
    t.diagnostic(`FAIL (expected) ${label}`);
  }
});

test('normalization strips every specified control after NFKC', () => {
  const controls = [0x200B, 0x200C, 0x200D, 0x200E, 0x200F, 0x202A, 0x202B, 0x202C,
    0x202D, 0x202E, 0x2060, 0x2061, 0x2062, 0x2063, 0x2064, 0x2066, 0x2067, 0x2068, 0x2069, 0xFEFF];
  for (const codepoint of controls) {
    assert.equal(normalize(`Ｃｏ${String.fromCodePoint(codepoint)}ｄｅｘ`), 'Codex');
  }
});

