test('text warnings annotate without denying ordinary vendor references', () => {
  const result = inspectPullRequest({ ...cleanPR, title: 'Update Claude SDK integration' });
  assert.deepEqual(result.denied, []);
  assert.equal(result.warnings[0].field, 'PR title');
});

function harness(commits = [cleanCommit], changes = {}) {
  const pr = {
    number: 44, head: { sha: cleanCommit.sha, ref: cleanPR.branch },
    user: { login: cleanPR.actor }, title: cleanPR.title, body: cleanPR.body,
    commits: commits.length, ...changes,
  };
  const calls = { rest: 0, graphql: 0, info: [], warning: [], error: [], failed: [] };
  const core = {
    info: message => calls.info.push(message), warning: message => calls.warning.push(message),
    error: message => calls.error.push(message), setFailed: message => calls.failed.push(message),
  };
  const context = { repo: { owner: 'BichengWang', repo: 'multi-agents' }, payload: { pull_request: structuredClone(pr) } };
  const github = {
    rest: { pulls: { get: async () => { calls.rest++; return { data: structuredClone(pr) }; } } },
    graphql: async (query, variables) => {
      calls.graphql++;
      const offset = Number(variables.cursor ?? 0);
      const next = offset + 100;
      return { repository: { pullRequest: {
        headRefOid: pr.head.sha,
        commits: {
          totalCount: commits.length,
          nodes: commits.slice(offset, next).map(commit => ({ commit: { ...commit, oid: commit.sha } })),
          pageInfo: { hasNextPage: next < commits.length, endCursor: String(next) },
        },
      } } };
    },
  };
  return { github, core, context, calls, pr };
}

test('the guard reads all pages and denies a prohibited 251st commit', async () => {
  const commits = Array.from({ length: 251 }, (_, index) => ({ ...cleanCommit, sha: index.toString(16).padStart(40, '0') }));
  commits[250].message = 'Co-authored-by: Codex <helper@example.com>';
  const h = harness(commits);
  await run(h);
  assert.equal(h.calls.graphql, 3);
  assert.equal(h.calls.rest, 2);
  assert.equal(h.calls.failed.length, 1);
  assert.match(h.calls.error[0], new RegExp(commits[250].sha));
});

test('the guard emits warnings and succeeds on a clean PR', async () => {
  const h = harness([cleanCommit], { title: 'Update Claude SDK integration' });
  await run(h);
  assert.equal(h.calls.warning.length, 1);
  assert.deepEqual(h.calls.failed, []);
  assert.match(h.calls.info.at(-1), /all 1 commits/u);
});

test('a dependabot PR passes using its API author, not the workflow actor', async () => {
  const h = harness([cleanCommit], { user: { login: 'dependabot[bot]' }, head: { sha: cleanCommit.sha, ref: 'dependabot/npm_and_yarn/openai-1' } });
  h.context.actor = 'BichengWang';
  await run(h);
  assert.deepEqual(h.calls.failed, []);
  assert.equal(h.calls.graphql, 0);
  const spoof = harness([cleanCommit], { head: { sha: cleanCommit.sha, ref: 'codex/x' } });
  spoof.context.actor = 'dependabot[bot]';
  await run(spoof);
  assert.equal(spoof.calls.failed.length, 1);
});

test('the guard fails closed on a changed head or an incomplete commit list', async () => {
  const changed = harness();
  changed.context.payload.pull_request.head.sha = 'b'.repeat(40);
  await assert.rejects(run(changed), /PR head changed/u);
  const incomplete = harness();
  const graphql = incomplete.github.graphql;
  incomplete.github.graphql = async (...args) => {
    const response = await graphql(...args);
    response.repository.pullRequest.commits.nodes = [];
    return response;
  };
  await assert.rejects(run(incomplete), /every PR commit/u);
});

test('the guard fails closed when metadata changes during verification', async () => {
  const h = harness();
  const get = h.github.rest.pulls.get;
  h.github.rest.pulls.get = async (...args) => {
    const response = await get(...args);
    if (h.calls.rest === 2) response.data.body = 'Generated with Codex';
    return response;
  };
  await assert.rejects(run(h), /PR changed during verification/u);
});
